-- | Scenario names and descriptions are stable report and selection interfaces.
module Ecluse.BenchLoad.Contract.DriverSpec (spec) where

import Test.Hspec

import Ecluse.BenchLoad.Harness (Scenario (scenarioDescription, scenarioName), UpstreamFixture (fixtureScenarios))
import Ecluse.BenchLoad.Npm (npmFixture)
import Ecluse.BenchLoad.PyPI (pypiFixture)

spec :: Spec
spec = describe "load scenario reporting contract" $
    for_ [("npm", npmFixture, npmExpected), ("pypi", pypiFixture, pypiExpected)] $ \(name, fixture, expected) ->
        it (name <> " preserves every scenario name and description in order") $
            map (\item -> (scenarioName item, scenarioDescription item)) (fixtureScenarios fixture) `shouldBe` expected

npmExpected :: [(Text, Text)]
npmExpected =
    [ ("merge-cold", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0. Concurrent public misses share one fetch and decode. Every request reads private metadata, merges, filters, rewrites URLs, and serialises.")
    , ("merge-cold-advisories", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0. Concurrent public misses share one fetch and decode. Every request reads private metadata, merges, filters, rewrites URLs, and serialises. The proxy syncs an advisory database compiled from the captured corpus advisories, under the shipped policy.")
    , ("merge-cold-all-advisory-rules", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0. Concurrent public misses share one fetch and decode. Every request reads private metadata, merges, filters, rewrites URLs, and serialises. The proxy syncs an advisory database compiled from the captured corpus advisories, and its policy adds DenyIfCve at CVSS 8 (onUnavailable deny) and DenyIfEpss at 0.5 (onUnavailable deny).")
    , ("heavy-private-5pct", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0, while the private upstream returns the newest 5% of each capture's versions by publish time, rounded up to a whole version, as a mirror target that has mirrored those versions does. The private copy stays fixed for the run. Each request decodes its own private copy, which single-flight cannot share across callers.")
    , ("heavy-private-25pct", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0, while the private upstream returns the newest 25% of each capture's versions by publish time, rounded up to a whole version, as a mirror target that has mirrored those versions does. The private copy stays fixed for the run. Each request decodes its own private copy, which single-flight cannot share across callers.")
    , ("heavy-private", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0, while the private upstream returns the complete public capture, as a private registry that proxies npmjs does. Each request decodes its own private copy, which single-flight cannot share across callers.")
    , ("slow-readers", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0, as merge-cold does. The figures are that load's, measured while the same number of further clients request the same listings and read each response at 1024 KiB/s over 1448-byte segments. After a refusal or a failure, a slow reader waits one second before it asks again.")
    , ("assembled-response-hit", "GET /npm/{pkg} over the weighted corpus with retained assembled responses. Each request fetches full public and private metadata, except overlapping public reads share active work.")
    , ("revalidate-not-modified", "GET the heaviest corpus packument with a primed If-None-Match validator. Each request reads private metadata and computes the plan, then returns 304 without assembly or encoding.")
    , ("revalidate-not-modified-advisories", "GET the heaviest corpus packument with a primed If-None-Match validator. Each request reads private metadata and computes the plan, then returns 304 without assembly or encoding. The proxy syncs an advisory database compiled from the captured corpus advisories, under the shipped policy.")
    , ("cache-fits-large", "GET a uniform corpus working set with enough assembled-response slots for every project. Full public metadata is always fetched. Compare with cache-evicts-large for assembly reuse.")
    , ("cache-evicts-large", "GET the same uniform corpus working set with min(configured entries, project count - 1) slots, forcing repeated assembly. Full public metadata is always fetched.")
    , ("tarball-hot-path", "GET /npm/{pkg}/-/{unscoped-pkg}-9999.0.2.tgz. Resolve the private artifact and stream its bytes from the local upstream.")
    , ("tarball-onboarding", "GET /npm/{pkg}/-/{unscoped-pkg}-1.0.0.tgz. A private 404 precedes public admission and artifact streaming. The private probe and public artifact add two sequential upstream waits. The mount mirrors nothing, so no mirror job is enqueued.")
    , ("tarball-ceiling", "Measure the private artifact relay at four times the base concurrency under load, one connection for service time, and 2 ms upstream latency. The payload knob sets the streamed body size.")
    , ("herd", "Send 100 simultaneous cold GET /npm/typescript to an idle proxy, once, with public cache TTL 0 and no warm-up. Any admission that reacts to measured memory sees this burst late.")
    , ("herd-under-heavy-private", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0, while the private upstream returns the complete public capture, as a private registry that proxies npmjs does. Halfway through the window, 100 more connections each send one request for the typescript listing, all at once. The harness reads the proxy cgroup's memory every 10 ms until that burst ends.")
    , ("warm-under-cold", "With cache TTL 3600, measure assembled-response hits and retained selected-version reads for the corpus outside the heavy tier, while a second generator drives listings of the heavy tier at the same concurrency. The heavy tier's private documents change on every request, so those listings never reuse an assembled response.")
    , ("ramp", "GET /npm/{pkg} over the weighted corpus with public cache TTL 0, holding 10, 25, 50, 100, 200, 400 connections in turn for the configured duration each. Successes should level off past saturation, not fall.")
    , ("worker-mirroring", "Run the mirror worker fetch, integrity check, publish, and acknowledgement loop in the harness process. The initial presence probe reports absent and the final probe confirms the write, so every job exercises the complete pipeline.")
    , ("pattern-hot-set-control", "Staggered clients repeatedly request the same package set. The run includes the first cold requests and later reuse. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds.")
    , ("pattern-cold-install", "One client requests each selected package once, without repeats. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds.")
    , ("pattern-ci-fleet", "Staggered clients each request the same package sequence once, modelling CI builds with matching dependency lists. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds.")
    , ("pattern-heterogeneous", "Staggered clients each request a partly shared package list once. The overlap fraction sets the common packages. Each client's remaining packages are disjoint. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds.")
    , ("pattern-zipf", "Staggered clients sample packages with a Zipf distribution: higher-ranked packages receive more requests. The exponent controls skew, and the seed fixes the finite draws. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds.")
    , ("pattern-restart", "Clients arrive at fixed intervals into a fresh proxy with empty caches, each requesting the same package sequence once. No running proxy is restarted. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds.")
    , ("pattern-scan", "One client repeatedly scans the entire selected package set in order. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds.")
    , ("pattern-cold-install-default-body-cap", "One client requests each selected package once, without repeats. Each client sends sequential requests over captured package names. Every scenario starts with a fresh proxy and empty stores. Cache TTL is 60 seconds. The production response body cap applies, so oversized metadata receives a refusal.")
    ]

